// NOLINTEND

bool differenceTest(double sqNormFix1, double sqNormFix2, double criticalValue)
{
    return sqNormFix2 - sqNormFix1 >= criticalValue;
}

bool ratioTest(double sqNormFix1, double sqNormFix2, double mu)
{
    return sqNormFix1 / sqNormFix2 <= mu;
}

double criticalValueFailureRateLookup(double Pf, double Pf_ILS, size_t nAmb)
{
    INS_ASSERT_USER_ERROR(Pf == 0.001 || Pf == 0.01, "Only lookup-tables for Pf = 0.1% or 1% exist.");
    INS_ASSERT_USER_ERROR(Pf_ILS >= 0 && Pf_ILS <= 1.0, "Pf_ILS needs to be between 0 and 1");
    if (nAmb == 0)
    {
        LOG_ERROR("Need at least 1 ambiguity.");
        return 0.0;
    }

    const auto& table = lookupTableFailureProbability.at(Pf);
    nAmb = std::min(nAmb, table[0].size()); // Limit nAmb to the table size

    for (size_t i = 0; i < table.size() - 1; i++)
    {
        if (table[i][0] <= Pf_ILS && Pf_ILS <= table[i + 1][0])
        {
            double t = (Pf_ILS - table[i][0]) / (table[i + 1][0] - table[i][0]);
            return std::lerp(table[i][nAmb - 1], table[i + 1][nAmb - 1], t);
        }
    }

    LOG_ERROR("Ambiguity resolution critical value lookup did not work (please contact a developer).");
    return 0.0; // This should not happen.
}

